 @Test void acceptsReportedAndVerifiedEvidenceRejectsTerminalAndPaginatesPrivately()throws Exception{seed("reported","REPORTED");seed("verified","VERIFIED");seed("archived","ARCHIVED");seed("rejected","REJECTED");seed("duplicate","DUPLICATE");String a=create("reported","");Thread.sleep(2);String b=create("reported","");create("verified","");for(String id:new String[]{"archived","rejected","duplicate"})mvc.perform(post("/api/v1/events/{id}/evidence",id).header("X-User-Id",OWNER).contentType(MediaType.APPLICATION_JSON).content(body(""))).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("EVENT_NOT_ACCEPTING_EVIDENCE"));mvc.perform(post("/api/v1/events/{id}/evidence","00000000-0000-0000-0000-000000000404").header("X-User-Id",OWNER).contentType(MediaType.APPLICATION_JSON).content(body(""))).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("EVENT_NOT_FOUND"));Assertions.assertEquals("reported",jdbc.queryForObject("SELECT event_id FROM evidence WHERE id=?",String.class,a));Assertions.assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM evidence WHERE id=? AND submitter_user_id=? AND public_location_description='public' AND exact_location_description='exact' AND latitude IS NOT NULL AND longitude IS NOT NULL AND created_at IS NOT NULL",Integer.class,a,OWNER));mvc.perform(get("/api/v1/events/{id}/evidence","reported").header("X-User-Id",OTHER).param("page","0").param("size","1")).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(2)).andExpect(jsonPath("$.items[0].id").value(a)).andExpect(jsonPath("$.items[0].exactLocationDescription").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.items[0].latitude").value(org.hamcrest.Matchers.nullValue()));mvc.perform(get("/api/v1/events/{id}/evidence","reported").param("page","1").param("size","1")).andExpect(jsonPath("$.items[0].id").value(b));}
 @Test void exposesExactLocationOnlyToEvidenceSubmitterEventReporterAndAdmin()throws Exception{seed("reported","REPORTED");String response=mvc.perform(post("/api/v1/events/{id}/evidence","reported").header("X-User-Id",OTHER).contentType(MediaType.APPLICATION_JSON).content(body(""))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String id=mapper.readTree(response).required("id").asText();for(String viewer:new String[]{OTHER,OWNER,ADMIN})mvc.perform(get("/api/v1/events/{id}/evidence","reported").header("X-User-Id",viewer)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].id").value(id)).andExpect(jsonPath("$.items[0].exactLocationDescription").value("exact")).andExpect(jsonPath("$.items[0].latitude").value(31.1)).andExpect(jsonPath("$.items[0].longitude").value(121.2));mvc.perform(get("/api/v1/events/{id}/evidence","reported").header("X-User-Id","00000000-0000-0000-0000-000000000103")).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].exactLocationDescription").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.items[0].latitude").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.items[0].longitude").value(org.hamcrest.Matchers.nullValue()));}
 @Test void formalizesImageAndVideoAndRejectsUnsafeMediaWithoutRows()throws Exception{seed("reported","REPORTED");put("incident-input/"+OWNER+"/a.jpg","image/jpeg","image");put("incident-input/"+OWNER+"/b.mp4","video/mp4","video");String id=create("reported",",\"media\":[{\"temporaryObjectKey\":\"incident-input/"+OWNER+"/a.jpg\",\"contentType\":\"image/jpeg\",\"sizeBytes\":5,\"sortOrder\":0},{\"temporaryObjectKey\":\"incident-input/"+OWNER+"/b.mp4\",\"contentType\":\"video/mp4\",\"sizeBytes\":5,\"sortOrder\":1}]");Assertions.assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM evidence_media WHERE evidence_id=?",Integer.class,id));Assertions.assertEquals(5,minio.statObject(StatObjectArgs.builder().bucket(BUCKET).object("evidence/"+id+"/00.jpg").build()).size());Assertions.assertEquals(5,minio.statObject(StatObjectArgs.builder().bucket(BUCKET).object("evidence/"+id+"/01.mp4").build()).size());mvc.perform(get("/api/v1/events/{id}/evidence","reported")).andExpect(jsonPath("$.items[0].media.length()").value(2)).andExpect(jsonPath("$.items[0].media[0].readUrl",org.hamcrest.Matchers.containsString("X-Amz-Expires=600")));int before=jdbc.queryForObject("SELECT COUNT(*) FROM evidence",Integer.class);for(String suffix:new String[]{",\"media\":[{\"temporaryObjectKey\":\"incident-input/"+OWNER+"/x\",\"contentType\":\"application/pdf\",\"sizeBytes\":1,\"sortOrder\":0}]",",\"media\":[{\"temporaryObjectKey\":\"incident-input/"+OTHER+"/x\",\"contentType\":\"image/jpeg\",\"sizeBytes\":1,\"sortOrder\":0}]"})mvc.perform(post("/api/v1/events/{id}/evidence","reported").header("X-User-Id",OWNER).contentType(MediaType.APPLICATION_JSON).content(body(suffix))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_MEDIA"));mvc.perform(post("/api/v1/events/{id}/evidence","reported").header("X-User-Id",OWNER).contentType(MediaType.APPLICATION_JSON).content(body(",\"media\":[{\"temporaryObjectKey\":\"incident-input/"+OWNER+"/missing.jpg\",\"contentType\":\"image/jpeg\",\"sizeBytes\":1,\"sortOrder\":0}]"))).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("MINIO_UNAVAILABLE"));Assertions.assertEquals(before,jdbc.queryForObject("SELECT COUNT(*) FROM evidence",Integer.class));}
 @Test void rejectsOversizedAndMetadataMismatchedMedia()throws Exception{seed("reported","REPORTED");put("incident-input/"+OWNER+"/real.jpg","image/jpeg","real");for(String suffix:new String[]{",\"media\":[{\"temporaryObjectKey\":\"incident-input/"+OWNER+"/real.jpg\",\"contentType\":\"video/mp4\",\"sizeBytes\":4,\"sortOrder\":0}]",",\"media\":[{\"temporaryObjectKey\":\"incident-input/"+OWNER+"/large.jpg\",\"contentType\":\"image/jpeg\",\"sizeBytes\":10485761,\"sortOrder\":0}]",",\"media\":[{\"temporaryObjectKey\":\"incident-input/"+OWNER+"/large.mp4\",\"contentType\":\"video/mp4\",\"sizeBytes\":10485761,\"sortOrder\":0}]"})mvc.perform(post("/api/v1/events/{id}/evidence","reported").header("X-User-Id",OWNER).contentType(MediaType.APPLICATION_JSON).content(body(suffix))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_MEDIA"));} @Test void databaseForeignKeysAndMediaUniqueConstraintAreEnforced()throws Exception{seed("reported","REPORTED");String evidence=create("reported","");jdbc.update("INSERT INTO evidence_media (id,evidence_id,object_key,content_type,size_bytes,sort_order,created_at) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP)","m1",evidence,"evidence/"+evidence+"/x.jpg","image/jpeg",1,0);Assertions.assertThrows(DataIntegrityViolationException.class,()->jdbc.update("INSERT INTO evidence_media (id,evidence_id,object_key,content_type,size_bytes,sort_order,created_at) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP)","m2",evidence,"evidence/"+evidence+"/x.jpg","image/jpeg",1,1));Assertions.assertThrows(DataIntegrityViolationException.class,()->jdbc.update("INSERT INTO evidence (id,event_id,submitter_user_id,description,occurred_at,created_at) VALUES (?,?,?,?,?,CURRENT_TIMESTAMP)","bad","missing",OWNER,"x",Timestamp.from(Instant.now())));Assertions.assertThrows(DataIntegrityViolationException.class,()->jdbc.update("INSERT INTO evidence_media (id,evidence_id,object_key,content_type,size_bytes,sort_order,created_at) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP)","bad","missing","x","image/jpeg",1,0));}
 String create(String event,String suffix)throws Exception{String r=mvc.perform(post("/api/v1/events/{id}/evidence",event).header("X-User-Id",OWNER).contentType(MediaType.APPLICATION_JSON).content(body(suffix))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return mapper.readTree(r).required("id").asText();}String body(String suffix){return "{\"description\":\"e\",\"occurredAt\":\"2026-10-01T00:00:00Z\",\"publicLocationDescription\":\"public\",\"exactLocationDescription\":\"exact\",\"latitude\":31.1,\"longitude\":121.2"+suffix+"}";}void put(String k,String type,String text)throws Exception{byte[] b=text.getBytes(StandardCharsets.UTF_8);minio.putObject(PutObjectArgs.builder().bucket(BUCKET).object(k).stream(new ByteArrayInputStream(b),b.length,-1).contentType(type).build());}void seed(String id,String status){Timestamp t=Timestamp.from(Instant.parse("2026-10-01T00:00:00Z"));jdbc.update("INSERT INTO event_draft(id,user_id,campus_id,description,occurred_at,public_location_description,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)","d-"+id,OWNER,CAMPUS,"d",t,"p",t,t);jdbc.update("INSERT INTO event(id,source_draft_id,reporter_user_id,campus_id,description,occurred_at,reported_at,public_location_description,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,"d-"+id,OWNER,CAMPUS,"e",t,t,"p",status,t,t);}
